previewCss:
.darma-loader-darma-b17-beehive-frames { --accent: var(--loader-color, #a16207); --accent-2: var(--loader-secondary-color, #fbbf24); width: var(--loader-size, 122px); height: calc(var(--loader-size, 122px) * .72); position: relative; }
.darma-loader-darma-b17-beehive-frames .darma-loader-darma-b17-beehive-frames__box { position: absolute; inset: 0; border-radius: 6px; background: color-mix(in srgb, var(--accent) 18%, transparent); box-shadow: inset 0 0 0 3px color-mix(in srgb, var(--accent) 55%, transparent); }
.darma-loader-darma-b17-beehive-frames span { position: absolute; top: 8%; width: 20%; height: 84%; border-radius: 3px; background: linear-gradient(color-mix(in srgb, #fff 14%, var(--accent)), var(--accent)); overflow: hidden; animation: darma-loader-darma-b17-beehive-frames-hive-pull calc(var(--loader-speed, 1s) * 3.2) ease-in-out infinite; }
.darma-loader-darma-b17-beehive-frames span::after { content: ''; position: absolute; left: 10%; right: 10%; bottom: 6%; height: 0; background: repeating-conic-gradient(from 30deg at 50% 50%, var(--accent-2) 0 16.7%, color-mix(in srgb, #000 12%, var(--accent-2)) 0 33.3%); background-size: 34% 34%; animation: darma-loader-darma-b17-beehive-frames-hive-comb calc(var(--loader-speed, 1s) * 3.2) ease-in-out infinite; }
.darma-loader-darma-b17-beehive-frames span:nth-of-type(1) { left: 6%; }
.darma-loader-darma-b17-beehive-frames span:nth-of-type(2) { left: 29%; animation-delay: calc(var(--loader-speed, 1s) * .32); }
.darma-loader-darma-b17-beehive-frames span:nth-of-type(3) { left: 52%; animation-delay: calc(var(--loader-speed, 1s) * .64); }
.darma-loader-darma-b17-beehive-frames span:nth-of-type(4) { left: 75%; animation-delay: calc(var(--loader-speed, 1s) * .96); }
@keyframes darma-loader-darma-b17-beehive-frames-hive-pull { 0%, 12% { transform: translateY(0); } 34%, 62% { transform: translateY(-9%); } 86%, 100% { transform: translateY(0); } }
@keyframes darma-loader-darma-b17-beehive-frames-hive-comb { 0%, 10% { height: 0; } 46%, 74% { height: 86%; } 94%, 100% { height: 0; } }

